mapper.insert:
    SELECT
        'REFU'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(REFUND_NO), LENGTH('REFU' ) + 1)), 0) + 1, 6, '0')
    FROM REFUND

INSERT INTO REFUND (
REFUND_NO
	, PAYMENT_NO
	, REFUND_ACCOUNT
	, REFUND_REASON
	, REFUND_RATIO
	, PRODUCT_NAME
	, PAYMENT_PAY
) VALUES (
#{refundNo}
	, #{paymentNo}
	, #{refundAccount}
	, #{refundReason}
	, #{refundRatio}
	, #{productName}
	, #{paymentPay}
)

mapper.update:
UPDATE REFUND
SET 
PAYMENT_NO = #{paymentNo}
	, REFUND_ACCOUNT = #{refundAccount}
	, REFUND_REASON = #{refundReason}
	, REFUND_RATIO = #{refundRatio}
	, PRODUCT_NAME = #{productName}
	, PAYMENT_PAY = #{paymentPay}
WHERE REFUND_NO = #{refundNo}
